import { IProduct } from '@apps/Products/@types/products.types';
import { showModal } from '@ui-kit/Modal/modalsHelper';

import ProductSelectModal from './index';

export const selectProductAsync = (
  excludeIds?: number[],
  title = 'Выбор продукта',
): Promise<IProduct> => {
  return new Promise<IProduct>((res, rej) => {
    showModal({
      onClose: rej,
      title,
      size: 'sm',
      children: (close: () => void) => (
        <ProductSelectModal
          excludeIds={excludeIds}
          onSelect={(v) => {
            res(v);
            close();
          }}
        />
      ),
    });
  });
};
